using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckMinefield.Editor {
public static class MinefieldLandscapeAuthoring {
 public static void Install(MinefieldMatch m){var prior=GameObject.Find("Minefield surrounding meadow and landing runout");if(prior!=null)Object.DestroyImmediate(prior);var root=new GameObject("Minefield surrounding meadow and landing runout").transform;var left=Ground(m,root,"West meadow",new Vector3(-307,0,-12),new Vector3(250,35,8400),-1);var right=Ground(m,root,"East meadow",new Vector3(57,0,-12),new Vector3(250,35,8400),1);var runout=Ground(m,root,"Mile landing runout",new Vector3(-57,0,1668),new Vector3(114,35,6720),0);m.grounds=new[]{m.terrain,left,right,runout};for(int i=0;i<192;i++){float z=25+i/2*86;float x=(i%2==0?-1:1)*(80+i%7*22);var p=m.Surface(new Vector3(x,0,z));LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,p,i%4==0?3:8+i%3,i%4!=0,MinefieldAuthoring.Folder);}foreach(var t in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(t=>t.name=="Mile finish tower")){t.position=m.Surface(new Vector3(Mathf.Sign(t.position.x)*55,0,MinefieldRules.Mile))+Vector3.up*7;}
 var line=new GameObject("Terrain-following one-mile finish stripe");line.transform.SetParent(root,false);var mesh=new Mesh{name="Painted mile finish stripe"};var vertices=new Vector3[66];var uv=new Vector2[66];var triangles=new int[32*6];for(int i=0;i<33;i++){float x=Mathf.Lerp(-55,55,i/32f);for(int k=0;k<2;k++){vertices[i*2+k]=m.Surface(new Vector3(x,0,MinefieldRules.Mile+(k==0?-.6f:.6f)))+Vector3.up*.035f;uv[i*2+k]=new Vector2(i,k);}if(i<32){int a=i*2,t=i*6;triangles[t]=a;triangles[t+1]=a+1;triangles[t+2]=a+3;triangles[t+3]=a;triangles[t+4]=a+3;triangles[t+5]=a+2;}}mesh.vertices=vertices;mesh.uv=uv;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();const string path="Assets/TruckMinefield/Materials/Mile finish stripe.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(mesh,path);else{old.Clear();old.vertices=vertices;old.uv=uv;old.triangles=triangles;old.RecalculateNormals();old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);Object.DestroyImmediate(mesh);mesh=old;}line.AddComponent<MeshFilter>().sharedMesh=mesh;line.AddComponent<MeshRenderer>().sharedMaterial=SportsEventAuthoring.Mat(MinefieldAuthoring.Folder,"Mile stripe ivory",new Color(.88f,.97f,.72f));Props(m,root);foreach(var camera in m.views.views)camera.view.farClipPlane=10000;m.views.broadcast.view.farClipPlane=10000;EditorUtility.SetDirty(m);}
 static void Props(MinefieldMatch m,Transform root){var contact=SportsEventAuthoring.Contact(MinefieldAuthoring.Folder,"Old wreck and fence contact",.4f,.08f);for(int i=0;i<4;i++){var g=new GameObject("Old physical minefield truck wreck "+i);g.transform.SetParent(root,false);g.transform.position=m.Surface(new Vector3(i%2==0?-43:43,0,210+i*310))+Vector3.up*.9f;g.transform.rotation=Quaternion.Euler(0,i*77,78);var art=Object.Instantiate(m.racers[i].truck.visuals.gameObject,g.transform,false);foreach(var r in art.GetComponentsInChildren<Renderer>())if(r.name=="Cab"){var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",new Color(.28f,.17f,.10f));r.SetPropertyBlock(block);}var box=g.AddComponent<BoxCollider>();box.center=m.racers[i].truck.shape.center;box.size=m.racers[i].truck.shape.size;box.sharedMaterial=contact;}for(int i=0;i<64;i++){var g=new GameObject("Installed field-edge fence "+i);g.transform.SetParent(root,false);g.transform.position=m.Surface(new Vector3(i%2==0?-55.8f:55.8f,0,30+i/2*49));LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(g.transform,"Assets/JC_LP_MegaCity/Prefabs/FloorProps/SM_FloorProps_Fence_01.prefab",new Vector3(8,1.6f,2),0);g.transform.rotation=Quaternion.Euler(0,90,0);Bounds bounds=default;bool first=true;foreach(var f in g.GetComponentsInChildren<MeshFilter>()){var b=f.sharedMesh.bounds;for(int k=0;k<8;k++){var p=g.transform.InverseTransformPoint(f.transform.TransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((k&1)==0?-1:1,(k&2)==0?-1:1,(k&4)==0?-1:1))));if(first){bounds=new Bounds(p,Vector3.zero);first=false;}else bounds.Encapsulate(p);}}var shape=g.AddComponent<BoxCollider>();shape.center=bounds.center;shape.size=bounds.size;shape.sharedMaterial=contact;}}
 static Terrain Ground(MinefieldMatch m,Transform root,string name,Vector3 origin,Vector3 size,int side){string path="Assets/TruckMinefield/Materials/"+name+".asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,path);}data.heightmapResolution=513;data.size=size;var heights=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++){float wx=origin.x+x/512f*size.x,wz=origin.z+z/512f*size.z;float edgeX=side==0?wx:side*57;float baseline=m.terrain.SampleHeight(new Vector3(edgeX,0,Mathf.Min(wz,1668)));float edge=side==0?Mathf.Clamp01((wz-1668)/120):Mathf.Clamp01((Mathf.Abs(wx)-57)/110);float hill=(Mathf.PerlinNoise(wx*.013f+31,wz*.008f+17)*12+3+Mathf.Sin(wz*.004f)*3)*Mathf.SmoothStep(0,1,edge);heights[z,x]=Mathf.Clamp01((baseline+hill)/35);}data.SetHeights(0,0,heights);data.terrainLayers=m.terrain.terrainData.terrainLayers;data.alphamapResolution=64;var alpha=new float[64,64,2];for(int z=0;z<64;z++)for(int x=0;x<64;x++){alpha[z,x,0]=.96f;alpha[z,x,1]=.04f;}data.SetAlphamaps(0,0,alpha);var ground=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();ground.name=name;ground.transform.SetParent(root,false);ground.transform.position=origin;ground.materialTemplate=m.terrain.materialTemplate;ground.drawInstanced=true;ground.heightmapPixelError=8;EditorUtility.SetDirty(data);return ground;}
}
}
